using System.Runtime.InteropServices;
using cTools.Core.Models;

namespace cTools.Core.Scanning;

public static class UwpScanner
{
    private static readonly string[] SkipPackagePrefixes =
    {
        "Microsoft.AutoGenerated",
        "Microsoft.Windows.ShellExperienceHost",
        "Microsoft.Windows.StartMenuExperienceHost",
        "Microsoft.Windows.Search",
        "Microsoft.Windows.ContentDeliveryManager",
        "Microsoft.Windows.CloudExperienceHost",
        "Microsoft.Windows.OOBE",
        "Microsoft.Windows.SecureAssessmentBrowser",
        "Microsoft.Windows.ParentalControls",
        "Microsoft.Windows.AssignedAccessLockApp",
        "Microsoft.Windows.Cortana",
        "Microsoft.Windows.XGpuEjectDialog",
        "Microsoft.Windows.PrintQueueActionCenter",
        "Microsoft.Windows.Win32WebViewHost",
        "Microsoft.Win32WebViewHost",
        "Microsoft.UI.",
        "Microsoft.VCLibs",
        "Microsoft.NET.",
        "Microsoft.Services.",
        "Microsoft.AAD.",
        "Microsoft.AccountsControl",
        "Microsoft.CredDialogHost",
        "Microsoft.LockApp",
        "Microsoft.PPIProjection",
        "MicrosoftWindows.Client."
    };

    public static IEnumerable<AppEntry> Scan()
    {
        var entries = new List<AppEntry>();
        object? shell = null;
        object? folder = null;
        object? items = null;
        try
        {
            var shellType = Type.GetTypeFromProgID("Shell.Application");
            if (shellType is null) return entries;
            shell = Activator.CreateInstance(shellType);
            if (shell is null) return entries;
            dynamic dynamicShell = shell;
            folder = dynamicShell.NameSpace("shell:AppsFolder");
            if (folder is null) return entries;
            dynamic dynamicFolder = folder;
            items = dynamicFolder.Items();
            if (items is null) return entries;
            dynamic dynamicItems = items;
            var count = (int)dynamicItems.Count;
            for (var index = 0; index < count; index++)
            {
                object? item = null;
                try
                {
                    item = dynamicItems.Item(index);
                    if (item is null) continue;
                    dynamic dynamicItem = item;
                    if ((bool)dynamicItem.IsFolder) continue;
                    var name = (string?)dynamicItem.Name;
                    var path = (string?)dynamicItem.Path;
                    if (string.IsNullOrWhiteSpace(name) || string.IsNullOrWhiteSpace(path)) continue;
                    // shell:AppsFolder 也会列出 Win32/URL/帮助项，真正 UWP 的 Path 是 AUMID（含 !，不含路径分隔符）。
                    if (!path.Contains('!', StringComparison.Ordinal) || path.Contains('\\') || path.Contains('/'))
                        continue;
                    if (SkipPackagePrefixes.Any(prefix => path.StartsWith(prefix, StringComparison.OrdinalIgnoreCase)))
                        continue;
                    entries.Add(new AppEntry
                    {
                        Name = name.Trim(),
                        Target = path,
                        ResolvedTarget = path,
                        AppUserModelId = path,
                        Kind = EntryKind.Uwp,
                        Source = EntrySource.Uwp,
                        Description = "UWP 应用",
                        Keywords = new List<string> { name }
                    });
                }
                catch
                {
                    // 单个 UWP 项读取失败不影响其他项。
                }
                finally
                {
                    Release(item);
                }
            }
        }
        catch (Exception ex)
        {
            Logging.Log.Error("枚举 UWP 应用失败", ex);
        }
        finally
        {
            Release(items);
            Release(folder);
            Release(shell);
        }
        return entries;
    }

    private static void Release(object? value)
    {
        if (value is not null && Marshal.IsComObject(value))
        {
            try { Marshal.FinalReleaseComObject(value); } catch { }
        }
    }
}
